<?php
declare(strict_types=1);
require_once __DIR__ . '/_bootstrap.php';
require_once __DIR__ . '/_crm.php';
$cid=crm_company_id();$uid=crm_user_id();
$q=trim((string)($_GET['q']??''));$state=strtoupper(trim((string)($_GET['state']??'')));if(!in_array($state,['','PENDENTE','CONCLUIDO'],true))$state='';
$dateFrom=trim((string)($_GET['date_from']??''));$dateTo=trim((string)($_GET['date_to']??''));$statusId=max(0,(int)($_GET['status_id']??0));$nextFrom=trim((string)($_GET['next_from']??''));$nextTo=trim((string)($_GET['next_to']??''));$responsible=max(0,(int)($_GET['responsible_user_id']??0));
$statusRows=crm_statuses($pdo,$cid,true);$users=crm_users($pdo,$cid,true);
$where=['a.company_id=?'];$params=[$cid];
if($q!==''){$tokens=array_slice(preg_split('/\s+/u',$q,-1,PREG_SPLIT_NO_EMPTY)?:[],0,6);foreach($tokens as $t){$like=nexa_search_like($t);$where[]='(a.customer_name LIKE ? OR a.phone LIKE ? OR a.document LIKE ? OR a.email LIKE ? OR a.address LIKE ? OR a.request_text LIKE ? OR a.pending_reason LIKE ?)';for($i=0;$i<7;$i++)$params[]=$like;}}
if($state!==''){$where[]='a.state=?';$params[]=$state;}if($dateFrom!==''){$where[]='DATE(a.created_at)>=?';$params[]=$dateFrom;}if($dateTo!==''){$where[]='DATE(a.created_at)<=?';$params[]=$dateTo;}if($statusId>0){$where[]='a.status_id=?';$params[]=$statusId;}if($nextFrom!==''){$where[]='a.next_contact_date>=?';$params[]=$nextFrom;}if($nextTo!==''){$where[]='a.next_contact_date<=?';$params[]=$nextTo;}if($responsible>0){$where[]='a.responsible_user_id=?';$params[]=$responsible;}
$sql="SELECT a.*,s.name status_name,s.color status_color,t.name service_type_name,u.name responsible_name FROM crm_attendances a LEFT JOIN crm_statuses s ON s.company_id=a.company_id AND s.id=a.status_id LEFT JOIN crm_service_types t ON t.company_id=a.company_id AND t.id=a.service_type_id LEFT JOIN users u ON u.company_id=a.company_id AND u.id=a.responsible_user_id WHERE ".implode(' AND ',$where)." ORDER BY CASE WHEN a.state='PENDENTE' THEN 0 ELSE 1 END, CASE WHEN a.next_contact_date IS NULL THEN 1 ELSE 0 END,a.next_contact_date ASC,a.updated_at DESC,a.id DESC LIMIT 1000";
$st=$pdo->prepare($sql);$st->execute($params);$rows=$st->fetchAll(PDO::FETCH_ASSOC)?:[];
$kpi=$pdo->prepare("SELECT SUM(CASE WHEN state='PENDENTE' THEN 1 ELSE 0 END) pendentes,SUM(CASE WHEN state='CONCLUIDO' THEN 1 ELSE 0 END) concluidos FROM crm_attendances WHERE company_id=?");$kpi->execute([$cid]);$k=$kpi->fetch(PDO::FETCH_ASSOC)?:[];
$columns=['data'=>'Data atendimento','nome'=>'Nome','telefone'=>'Telefone','temperatura'=>'Temperatura','proximo'=>'Próximo contato','status'=>'Status','pendencia'=>'Pendência','tipo'=>'Tipo','responsavel'=>'Responsável','solicitacao'=>'Solicitação','acoes'=>'Ações'];$prefs=crm_grid_preferences_load($pdo,$cid,'atendimentos',array_keys($columns));
crm_page_start('CRM - Atendimentos','crm_atendimentos');
?>
