<div class="crm-kpis"><div class="crm-kpi"><small>Atendimentos pendentes</small><strong><?=number_format((int)($k['pendentes']??0),0,',','.')?></strong></div><div class="crm-kpi"><small>Atendimentos fechados</small><strong><?=number_format((int)($k['concluidos']??0),0,',','.')?></strong></div></div>
