<div class="crm-field"><label>Status do atendimento</label><select name="status_id"><option value="0">Todos</option><?php foreach($statusRows as $s):?><option value="<?=(int)$s['id']?>" <?=$statusId===(int)$s['id']?'selected':''?>><?=crm_e($s['name'])?></option><?php endforeach;?></select></div>
<div class="crm-field"><label>Próximo contato inicial</label><input type="date" name="next_from" value="<?=crm_e($nextFrom)?>"></div><div class="crm-field"><label>Próximo contato final</label><input type="date" name="next_to" value="<?=crm_e($nextTo)?>"></div>
<div class="crm-field"><label>Situação</label><select name="state"><option value="">Todas</option><option value="PENDENTE" <?=$state==='PENDENTE'?'selected':''?>>Pendente</option><option value="CONCLUIDO" <?=$state==='CONCLUIDO'?'selected':''?>>Concluído</option></select></div>
