<?php foreach($columns as $key=>$label):?><th data-col="<?=crm_e($key)?>" class="<?=$key==='acoes'?'crm-actions-col':''?>"><div class="crm-th-inner"><?=crm_e($label)?></div></th><?php endforeach;?>
</tr></thead><tbody><?php if(!$rows):?><tr><td colspan="11" style="padding:28px;text-align:center;color:#64748b">Nenhum atendimento encontrado.</td></tr><?php endif;?><?php foreach($rows as $r):$color=crm_clean_color((string)($r['status_color']??'#2563EB'));?><tr>
<td data-col="data" data-sort="<?=crm_e((string)$r['created_at'])?>"><strong><?=crm_e(crm_datetime($r['created_at']))?></strong></td><td data-col="nome"><strong><?=crm_e(trim((string)$r['customer_name'])?:'Sem nome informado')?></strong><?php if((int)($r['person_id']??0)>0):?><div class="crm-muted">Cliente cadastrado #<?=(int)$r['person_id']?></div><?php endif;?></td><td data-col="telefone"><?=crm_e(trim((string)$r['phone'])?:'—')?></td><td data-col="temperatura" data-sort="<?=(int)($r['lead_temperature']??20)?>"><?=crm_temperature_badge($r['lead_temperature']??20)?></td><td data-col="proximo" data-sort="<?=crm_e((string)($r['next_contact_date']??''))?>"><strong><?=crm_e(crm_date($r['next_contact_date']))?></strong></td>
<td data-col="status"><?php if(trim((string)$r['status_name'])!==''):?><span class="crm-badge" style="background:<?=crm_e($color)?>18;color:<?=crm_e($color)?>;border:1px solid <?=crm_e($color)?>55"><span class="crm-status-dot" style="background:<?=crm_e($color)?>"></span><?=crm_e($r['status_name'])?></span><?php else:?>—<?php endif;?></td>
<td data-col="pendencia"><span class="crm-badge <?=crm_e(crm_state_class((string)$r['state']))?>"><?=crm_e(crm_state_label((string)$r['state']))?></span><?php if(trim((string)$r['pending_reason'])!==''):?><div class="crm-muted" title="<?=crm_e($r['pending_reason'])?>"><?=crm_e($r['pending_reason'])?></div><?php endif;?></td><td data-col="tipo"><?=crm_e(trim((string)$r['service_type_name'])?:'—')?></td><td data-col="responsavel"><?=crm_e(trim((string)$r['responsible_name'])?:'—')?></td><td data-col="solicitacao" title="<?=crm_e($r['request_text'])?>"><?=crm_e($r['request_text'])?></td><td data-col="acoes" class="crm-actions-col"><div class="crm-actions"><a class="crm-btn sm" href="crm_atendimento.php?id=<?=(int)$r['id']?>&view=1">Visualizar</a><a class="crm-btn sm primary" href="crm_tramitar.php?id=<?=(int)$r['id']?>">Tramitar</a></div></td>
</tr><?php endforeach;?></tbody></table></div></div></div>
